const HTML_PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Slate</title>\n<link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n  <div id=\"app\">\n    <div id=\"chat-pane\">\n      <div id=\"header\">\n        <h1>Slate</h1>\n        <span id=\"subtitle\">chat + live artifacts</span>\n      </div>\n      <div id=\"messages\"></div>\n      <form id=\"input-form\">\n        <textarea id=\"input\" placeholder=\"Ask Slate anything...\" rows=\"1\"></textarea>\n        <button type=\"submit\" id=\"send-btn\">Send</button>\n      </form>\n    </div>\n    <div id=\"artifact-pane\" class=\"hidden\">\n      <div id=\"artifact-header\">\n        <span id=\"artifact-title\">Artifact</span>\n        <button id=\"artifact-close\">\u00d7</button>\n      </div>\n      <iframe id=\"artifact-frame\" sandbox=\"allow-scripts\"></iframe>\n    </div>\n  </div>\n  <script src=\"/app.js\"></script>\n</body>\n</html>\n";
const CSS_CONTENT = "* { box-sizing: border-box; }\nhtml, body { height: 100%; margin: 0; font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif; background: #1b1b1f; color: #e6e6eb; }\n#app { display: flex; height: 100vh; }\n\n#chat-pane { display: flex; flex-direction: column; flex: 1 1 50%; min-width: 320px; border-right: 1px solid #2c2c33; }\n#header { padding: 16px 20px; border-bottom: 1px solid #2c2c33; display: flex; align-items: baseline; gap: 10px; }\n#header h1 { margin: 0; font-size: 20px; }\n#subtitle { color: #8a8a96; font-size: 13px; }\n\n#messages { flex: 1; overflow-y: auto; padding: 20px; display: flex; flex-direction: column; gap: 16px; }\n.msg { max-width: 85%; padding: 10px 14px; border-radius: 12px; line-height: 1.5; white-space: pre-wrap; word-wrap: break-word; }\n.msg.user { align-self: flex-end; background: #3a5bd9; color: white; }\n.msg.assistant { align-self: flex-start; background: #2a2a31; }\n.msg pre { background: #16161a; padding: 10px; border-radius: 8px; overflow-x: auto; margin: 8px 0; }\n.msg code { font-family: \"SF Mono\", Menlo, Consolas, monospace; font-size: 13px; }\n.artifact-chip { display: inline-flex; align-items: center; gap: 6px; background: #3a5bd9; color: white; padding: 6px 12px; border-radius: 8px; cursor: pointer; font-size: 13px; margin: 6px 0; border: none; }\n.artifact-chip:hover { background: #4a6be9; }\n\n#input-form { display: flex; gap: 10px; padding: 14px 20px; border-top: 1px solid #2c2c33; }\n#input { flex: 1; resize: none; background: #2a2a31; border: 1px solid #3a3a42; color: #e6e6eb; border-radius: 10px; padding: 10px 14px; font-size: 14px; font-family: inherit; max-height: 160px; }\n#input:focus { outline: none; border-color: #3a5bd9; }\n#send-btn { background: #3a5bd9; color: white; border: none; border-radius: 10px; padding: 0 20px; font-size: 14px; cursor: pointer; }\n#send-btn:hover { background: #4a6be9; }\n#send-btn:disabled { opacity: 0.5; cursor: default; }\n\n#artifact-pane { flex: 1 1 50%; display: flex; flex-direction: column; background: white; }\n#artifact-pane.hidden { display: none; }\n#artifact-header { display: flex; justify-content: space-between; align-items: center; padding: 10px 16px; background: #1b1b1f; color: #e6e6eb; border-bottom: 1px solid #2c2c33; }\n#artifact-close { background: none; border: none; color: #e6e6eb; font-size: 20px; cursor: pointer; line-height: 1; }\n#artifact-frame { flex: 1; border: none; width: 100%; }\n\n@media (max-width: 800px) {\n  #app { flex-direction: column; }\n  #chat-pane, #artifact-pane { flex: 1 1 auto; }\n}\n";
const JS_CONTENT = "const messagesEl = document.getElementById(\"messages\");\nconst form = document.getElementById(\"input-form\");\nconst input = document.getElementById(\"input\");\nconst sendBtn = document.getElementById(\"send-btn\");\nconst artifactPane = document.getElementById(\"artifact-pane\");\nconst artifactFrame = document.getElementById(\"artifact-frame\");\nconst artifactTitle = document.getElementById(\"artifact-title\");\nconst artifactClose = document.getElementById(\"artifact-close\");\n\nlet history = []; // {role, content}\nlet artifactCounter = 0;\nconst artifacts = {}; // id -> {code, lang}\n\nfunction escapeHtml(s) {\n  return s.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\");\n}\n\n// Splits text on fenced code blocks ```lang\\n...\\n``` and renders them.\n// Blocks tagged artifact-html / artifact-jsx / artifact-js get a clickable\n// \"open artifact\" chip instead of an inline dump, matching Claude's pattern.\nfunction renderContent(text) {\n  const parts = text.split(/```/);\n  let html = \"\";\n  for (let i = 0; i < parts.length; i++) {\n    if (i % 2 === 0) {\n      html += escapeHtml(parts[i]);\n    } else {\n      const firstNewline = parts[i].indexOf(\"\\n\");\n      const lang = firstNewline === -1 ? parts[i].trim() : parts[i].slice(0, firstNewline).trim();\n      const code = firstNewline === -1 ? \"\" : parts[i].slice(firstNewline + 1);\n      if (lang.startsWith(\"artifact-\")) {\n        const id = \"artifact-\" + artifactCounter++;\n        artifacts[id] = { code, lang: lang.replace(\"artifact-\", \"\") };\n        html += `<button class=\"artifact-chip\" data-artifact=\"${id}\">\u25b6 Open artifact (${lang.replace(\"artifact-\", \"\")})</button>`;\n      } else {\n        html += `<pre><code>${escapeHtml(code)}</code></pre>`;\n      }\n    }\n  }\n  return html;\n}\n\nfunction openArtifact(id) {\n  const art = artifacts[id];\n  if (!art) return;\n  artifactPane.classList.remove(\"hidden\");\n  artifactTitle.textContent = `Artifact \u2014 ${art.lang}`;\n  if (art.lang === \"html\") {\n    artifactFrame.srcdoc = art.code;\n  } else {\n    // jsx/js: wrap in a minimal HTML shell with React from CDN for live preview\n    artifactFrame.srcdoc = `<!DOCTYPE html><html><head>\n      <script src=\"https://unpkg.com/react@18/umd/react.development.js\"><\\/script>\n      <script src=\"https://unpkg.com/react-dom@18/umd/react-dom.development.js\"><\\/script>\n      <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"><\\/script>\n      </head><body><div id=\"root\"></div>\n      <script type=\"text/babel\">${art.code}<\\/script>\n      </body></html>`;\n  }\n}\n\nmessagesEl.addEventListener(\"click\", (e) => {\n  if (e.target.classList.contains(\"artifact-chip\")) {\n    openArtifact(e.target.dataset.artifact);\n  }\n});\n\nartifactClose.addEventListener(\"click\", () => {\n  artifactPane.classList.add(\"hidden\");\n});\n\nfunction addMessageEl(role) {\n  const el = document.createElement(\"div\");\n  el.className = `msg ${role}`;\n  messagesEl.appendChild(el);\n  messagesEl.scrollTop = messagesEl.scrollHeight;\n  return el;\n}\n\nasync function sendMessage(text) {\n  history.push({ role: \"user\", content: text });\n  const userEl = addMessageEl(\"user\");\n  userEl.textContent = text;\n\n  const assistantEl = addMessageEl(\"assistant\");\n  assistantEl.textContent = \"\u2026\";\n\n  sendBtn.disabled = true;\n  try {\n    const res = await fetch(\"/api/chat\", {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ messages: history }),\n    });\n\n    const reader = res.body.getReader();\n    const decoder = new TextDecoder();\n    let buffer = \"\";\n    let full = \"\";\n    let first = true;\n\n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      buffer += decoder.decode(value, { stream: true });\n      const lines = buffer.split(\"\\n\");\n      buffer = lines.pop();\n      for (const line of lines) {\n        if (!line.startsWith(\"data: \")) continue;\n        const payload = line.slice(6).trim();\n        if (payload === \"[DONE]\") continue;\n        try {\n          const parsed = JSON.parse(payload);\n          const token = parsed.response ?? \"\";\n          if (first) {\n            full = token;\n            first = false;\n          } else {\n            full += token;\n          }\n          assistantEl.innerHTML = renderContent(full);\n          messagesEl.scrollTop = messagesEl.scrollHeight;\n        } catch (_) {\n          // ignore partial/non-JSON lines\n        }\n      }\n    }\n    history.push({ role: \"assistant\", content: full });\n  } catch (err) {\n    assistantEl.textContent = \"Error: \" + err.message;\n  } finally {\n    sendBtn.disabled = false;\n  }\n}\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const text = input.value.trim();\n  if (!text) return;\n  input.value = \"\";\n  input.style.height = \"auto\";\n  sendMessage(text);\n});\n\ninput.addEventListener(\"input\", () => {\n  input.style.height = \"auto\";\n  input.style.height = Math.min(input.scrollHeight, 160) + \"px\";\n});\n\ninput.addEventListener(\"keydown\", (e) => {\n  if (e.key === \"Enter\" && !e.shiftKey) {\n    e.preventDefault();\n    form.requestSubmit();\n  }\n});\n";


const SYSTEM_PROMPT = "You are Slate, a helpful AI coding assistant. When you write a runnable HTML, CSS, JS, or React snippet that the user could preview live, wrap it in a fenced code block tagged `artifact-html`, `artifact-jsx`, or similar, the UI renders those in a live sandboxed preview panel. Normal code examples in other languages just use a normal fenced code block with the language name. Keep responses concise and direct.";

async function handleChat(request, env) {
  const body = await request.json();
  const messages = [{ role: "system", content: SYSTEM_PROMPT }, ...body.messages];
  try {
    const stream = await env.AI.run("@cf/meta/llama-3.1-8b-instruct", { messages, stream: true });
    return new Response(stream, { headers: { "content-type": "text/event-stream", "cache-control": "no-cache" } });
  } catch (err) {
    return mockStreamResponse(messages[messages.length - 1] && messages[messages.length - 1].content ? messages[messages.length - 1].content : "", err);
  }
}

function mockStreamResponse(userMessage, err) {
  const encoder = new TextEncoder();
  const errMsg = err && err.message ? err.message : String(err);
  const reply = "(mock response: AI binding error: " + errMsg + ")\n\nYou said: " + userMessage + "\n";
  const words = reply.split(/(\s+)/);
  const stream = new ReadableStream({
    async start(controller) {
      for (const w of words) {
        controller.enqueue(encoder.encode("data: " + JSON.stringify({ response: w }) + "\n\n"));
        await new Promise((r) => setTimeout(r, 10));
      }
      controller.enqueue(encoder.encode("data: [DONE]\n\n"));
      controller.close();
    },
  });
  return new Response(stream, { headers: { "content-type": "text/event-stream", "cache-control": "no-cache" } });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/chat" && request.method === "POST") {
      return handleChat(request, env);
    }
    if (url.pathname === "/style.css") {
      return new Response(CSS_CONTENT, { headers: { "content-type": "text/css" } });
    }
    if (url.pathname === "/app.js") {
      return new Response(JS_CONTENT, { headers: { "content-type": "application/javascript" } });
    }
    return new Response(HTML_PAGE, { headers: { "content-type": "text/html" } });
  },
};
